"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4820],{74820:d=>{d.exports=JSON.parse('{"schemaVersion":1,"locale":"ru","slug":"10-vychety","title":"Урок 10. Налоговые вычеты: Деньги, которые государство вернёт, если попросишь","sourceFingerprint":"4729302deaabf2e02aa87906fe4cd9c353ec21ba06e112dcf4f2e2cc16548a53","blocks":[{"id":"b001","markdown":"## Налоговые вычеты"},{"id":"b002","markdown":"Деньги, которые государство вернёт, если попросишь"},{"id":"b003","markdown":"Если ты работаешь официально, с зарплаты каждый месяц удерживают налог. Работодатель делает это сам, поэтому его почти никто не замечает."},{"id":"b004","markdown":"При этом в ряде случаев государство готово часть налога вернуть: за лечение, учёбу, спорт, покупку квартиры, вложения вдолгую и за детей. Про это многие слышали, но не оформляют, потому что представляют себе кипу бумаг и очереди в налоговой. На деле почти всё делается онлайн, а суммы выходят от нескольких тысяч до сотен тысяч рублей."},{"id":"b005","markdown":"### Как это работает"},{"id":"b006","markdown":"Налоговый вычет уменьшает доход, с которого считают налог."},{"id":"b007","markdown":"Например, ты заработал за год 900 000 ₽ и заплатил 13%, то есть 117 000 ₽. Потом потратил 100 000 ₽ на лечение зубов. Государство пересчитывает: облагаемый доход был 800 000 ₽, налог с него 104 000 ₽, значит 13 000 ₽ переплачены и их можно вернуть."},{"id":"b008","markdown":"Из этого следуют 3 правила."},{"id":"b009","markdown":"- Вернуть можно только налог, который ты заплатил. Не было официальной зарплаты, возвращать нечего."},{"id":"b010","markdown":"- Возвращают по твоей ставке. С 2025 года налог прогрессивный: 13% с дохода до 2,4 млн ₽ в год, 15% с части от 2,4 до 5 млн ₽, дальше 18%, 20% и 22%. Платишь 15%, вернут 15%."},{"id":"b011","markdown":"- Заявить вычет можно за 3 последних года. В 2026 году это расходы 2023, 2024 и 2025 годов."},{"id":"b012","markdown":"Получить вычет не смогут самозанятые на налоге на профессиональный доход и ИП на упрощёнке или патенте, если у них нет другого дохода с НДФЛ. Ещё неработающие без облагаемого дохода и налоговые нерезиденты, то есть те, кто провёл в России меньше 183 дней в году."},{"id":"b013","markdown":"И деталь из урока 6: на налог с процентов по вкладам вычеты не действуют, это отдельный налог."},{"id":"b014","markdown":"ВЫЧЕТ УМЕНЬШАЕТ ДОХОД ДЛЯ НАЛОГА ДОХОД 900 000 ₽ → НАЛОГ 117 000 ₽ 800 000 ₽ → НАЛОГ 104 000 ₽ 100 000 ₽ НА ЗУБЫ ВЕРНУТ 13 000 ₽ ₽"},{"id":"b015","markdown":"### Лечение, обучение и спорт"},{"id":"b016","markdown":"Лечение. Приём врачей, анализы, стоматология, лекарства по назначению врача и полис ДМС. Можно не только за себя, но и за супруга, родителей и детей до 18 лет. Если ребёнок учится очно, то до 24. У клиники должна быть лицензия, а тебе понадобится справка об оплате медицинских услуг для налоговой, её выдают в клинике. Многие клиники уже сами передают данные в налоговую."},{"id":"b017","markdown":"Дорогостоящее лечение из перечня правительства, например сложные операции, идёт без лимита: налог вернут со всей суммы. В справке у таких услуг стоит код 2. Обучение. Своё в любой форме: вуз, курсы, автошкола, повышение квалификации. Детей, братьев и сестёр очно до 24 лет, а также супруга. Лицензия у организации обязательна, проще всего спросить напрямую."},{"id":"b018","markdown":"Спорт. Фитнес, бассейн, спортивные секции, если организация есть в перечне Минспорта (его публикуют на региональных сайтах министерства). С 2026 года вычет можно получить и за спорт родителей-пенсионеров, если договор и оплата оформлены на тебя."},{"id":"b019","markdown":"Лимиты. Лечение, своё обучение и спорт вместе ограничены 150 000 ₽ расходов в год, это максимум 19 500 ₽ возврата при ставке 13%. На обучение детей отдельный лимит, 110 000 ₽ на каждого ребёнка. Дорогостоящее лечение без лимита."},{"id":"b020","markdown":"Важно: социальный вычет на следующий год не переносится. Если оплатить учёбу на несколько лет вперёд одним платежом, вычет дадут только в пределах лимита одного года, остальное сгорит. Если можно, плати по годам."},{"id":"b021","markdown":"### Дети"},{"id":"b022","markdown":"Стандартный вычет каждый месяц уменьшает облагаемую зарплату: на 1 400 ₽ за первого ребёнка, на 2 800 ₽ за второго и на 6 000 ₽ за третьего и каждого следующего. Он работает, пока сумма твоей зарплаты с января не перевалит за 450 000 ₽, и положен каждому из родителей. Оформляется заявлением в бухгалтерии, и если ты его не получаешь, стоит это заявление написать."},{"id":"b023","markdown":"Семейная налоговая выплата появилась в 2026 году для работающих родителей с 2 и более детьми. Условие такое: среднедушевой доход семьи не выше 1,5 регионального прожиточного минимума. Тогда государство возвращает часть НДФЛ, всё, что заплачено сверх 6%. Есть и другие условия, например отсутствие долгов по алиментам. Выплату может получить каждый из родителей."},{"id":"b024","markdown":"Заявление подают через Госуслуги или Социальный фонд с 1 июня по 1 октября за прошлый год. За 2025 год приём уже закрылся, за 2026 год откроется 1 июня 2027 года."},{"id":"b025","markdown":"### Квартира"},{"id":"b026","markdown":"Самый крупный вычет, и он бывает 2 видов. За покупку жилья налог возвращают с суммы до 2 млн ₽, это до 260 000 ₽ при ставке 13%. Если квартира обошлась дешевле, неиспользованную часть лимита можно перенести на другую покупку жилья. За проценты по ипотеке налог возвращают с выплаченных процентов до 3 млн ₽, это до 390 000 ₽. Этот вычет дают только по одному объекту."},{"id":"b027","markdown":"Вместе выходит до 650 000 ₽. Получать их можно постепенно, год за годом, пока лимит не кончится. Если жильё куплено в браке, право на вычет есть у каждого из супругов."},{"id":"b028","markdown":"### ГТО"},{"id":"b029","markdown":"С 2025 года есть вычет за сдачу нормативов ГТО на знак отличия: 18 000 ₽ в год, то есть 2 340 ₽ возврата при ставке 13%. С 2026 года для него хватает профилактического медосмотра, диспансеризация не обязательна. Сумма небольшая, но если ты и так ходишь в спортзал, почему нет."},{"id":"b030","markdown":"### Вложения вдолгую"},{"id":"b031","markdown":"Тем, кто копит надолго, государство тоже возвращает налог. Речь про индивидуальный инвестиционный счёт третьего типа (ИИС-3) и программу долгосрочных сбережений через негосударственный пенсионный фонд. Если вносить туда деньги, можно вернуть налог со взносов до 400 000 ₽ в год, то есть до 52 000 ₽ при ставке 13%. С 1 сентября 2026 года сюда же перенесли вычет за долгосрочное страхование жизни, и лимит 400 000 ₽ общий на все эти инструменты."},{"id":"b032","markdown":"У них есть условия по срокам. Например, ИИС-3, открытый в 2026 году, нужно держать минимум 5 лет. Иначе вычеты придётся вернуть. Подробно разберём в следующем модуле, вместе с инвестициями."},{"id":"b033","markdown":"Сколько вернёт государство?"},{"id":"b034","markdown":"Лечение, учёба, спорт Учёба ребёнка Покупка жилья Проценты по ипотеке Потратил 100\xa0000 ₽ Официальный доход за год 900\xa0000 ₽ 13\xa0000 ₽"},{"id":"b035","markdown":"вернут: 100\xa0000 ₽ \xd7 13% \xb7 общий лимит 150 000 ₽ расходов в год, не переносится"},{"id":"b036","markdown":"Проверь личный кабинет налоговой: часто заявление уже лежит там предзаполненным. Ставка 15% берётся с части дохода выше 2,4 млн ₽ в год; здесь для простоты она берётся на всю сумму."},{"id":"b037","markdown":"### Как получить деньги"},{"id":"b038","markdown":"Упрощённо, через личный кабинет налоговой или Госуслуги. Работает для расходов с 2024 года. Многие клиники, вузы, спортклубы и банки сами передают данные в налоговую, и она формирует предзаполненное заявление. Его остаётся проверить в личном кабинете налогоплательщика и подписать. Проверка обычно занимает до месяца, деньги приходят на счёт. Загляни туда, часто такое заявление уже лежит, а человек об этом не знает."},{"id":"b039","markdown":"Через банковское приложение. Некоторые крупные банки, например Сбер и Т-Банк, оформляют социальный вычет прямо в приложении. Это работает, если ты платил организации, которая сотрудничает с банком. Банк готовит заявление, ты подписываешь."},{"id":"b040","markdown":"Через работодателя, если не хочется ждать конца года. Подаёшь в налоговую заявление на подтверждение права на вычет. Примерно через месяц она присылает уведомление работодателю. После этого бухгалтерия перестаёт удерживать налог с зарплаты, пока не наберётся сумма вычета. Несколько месяцев зарплата на руки будет больше."},{"id":"b041","markdown":"Самостоятельно, декларацией 3-НДФЛ. Самый долгий путь, зато универсальный: годится для любого вычета и за любой из 3 лет. Заполняешь декларацию в личном кабинете налоговой и прикладываешь сканы: договор, справку или чеки, лицензию. Проверка до 3 месяцев и ещё до месяца на перевод денег."},{"id":"b042","markdown":"### Что сделать сейчас"},{"id":"b043","markdown":"- Зайди в личный кабинет налоговой и проверь, нет ли там предзаполненных заявлений."},{"id":"b044","markdown":"- Вспомни расходы за 2023, 2024 и 2025 годы: лечение, стоматология, учёба, спорт, квартира. Срок по 2023 году истекает в конце 2026-го."},{"id":"b045","markdown":"- Заведи папку, бумажную или в облаке, и складывай туда договоры, чеки и справки за 2026 год. В начале 2027-го это сэкономит время."},{"id":"b046","markdown":"- Проверь, получаешь ли ты стандартный вычет на детей на работе."},{"id":"b047","markdown":"### Самое главное"},{"id":"b048","markdown":"- Вычет возвращает часть уже заплаченного налога: не больше, чем заплатил, по твоей ставке и за последние 3 года."},{"id":"b049","markdown":"- Лечение, своё обучение и спорт: до 150 000 ₽ расходов в год. Обучение детей: до 110 000 ₽ на каждого. Дорогостоящее лечение без лимита."},{"id":"b050","markdown":"- Квартира: до 2 млн ₽ расходов на покупку и до 3 млн ₽ процентов по ипотеке."},{"id":"b051","markdown":"- Проще всего начать с предзаполненного заявления в личном кабинете налоговой."},{"id":"b052","markdown":"На этом уроки модуля закончились. Дальше 2 гайда: план на первые 30 дней и, для тех, кому это подходит, кредитка без процентов. А в следующем модуле разберёмся, как защищать накопления и с чего начинать инвестировать."}],"terms":[{"id":"iis","term":"ИИС (индивидуальный инвестиционный счёт)","definition":"счёт с налоговой льготой. Тип А: возврат 13% от взноса, до 52 000 ₽ в год. Тип Б: освобождение прибыли от налога. Трёхлетний отсчёт идёт с момента открытия"},{"id":"ndfl","term":"НДФЛ (налог на доходы физических лиц)","definition":"Налог на доходы физических лиц. В учебных расчётах этого курса используются 13% до 2,4 млн ₽ годового дохода и 15% для следующей ступени. С 2025 года основная шкала прогрессивная; для других видов дохода действуют особые правила. Актуальные ставки и право на вычет проверяйте у ФНС."},{"id":"prozhitochnyy-minimum","term":"Прожиточный минимум","definition":"сумма, которой, по расчёту государства, человеку хватает на базовые нужды за месяц. По ней решают, кому положены пособия, и её нельзя забрать у должника при взыскании долгов. Это граница выживания, а не нормальной жизни"},{"id":"oblako","term":"Облако (облачные сервисы)","definition":"аренда чужих серверов через интернет: компания платит за мощность, которой пользуется, и не строит свой дата-центр. Это дешевле и быстрее, но сайт или приложение зависит от того, работает ли площадка провайдера"}],"quizzes":[{"id":"10-vychety-q1","q":"Ты потратил 100 000 ₽ на стоматологию, твоя ставка НДФЛ 13%, налога за год заплачено 90 000 ₽. Сколько можно вернуть?","options":["100 000 ₽","90 000 ₽","13 000 ₽"],"correct":2},{"id":"10-vychety-q2","q":"Ты самозанятый и платишь только налог на профессиональный доход. Можешь ли ты получить социальный вычет за учёбу?","options":["Да, всегда","Нет, если у тебя нет дохода, с которого удерживается НДФЛ","Да, но только за учёбу детей"],"correct":1},{"id":"10-vychety-q3","q":"За какие годы в 2026 году можно заявить вычет за лечение?","options":["За 2023, 2024 и 2025 годы","Только за 2025 год","За любые годы с момента начала работы"],"correct":0}],"officialSources":[]}')}}]);